 { id: "home", label: "Home", icon: "M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6" },
 { id: "mybus", label: "My Bus", icon: "M4 16V6a4 4 0 014-4h8a4 4 0 014 4v10M4 16h16M4 16l-2 3h20l-2-3M8 20v1M16 20v1M8 10h8" },
 { id: "report", label: "Report", icon: "M12 9v2m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" },
 { id: "requests", label: "Requests", icon: "M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" },
 { id: "profile", label: "Profile", icon: "M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" },
];

export default function BottomNav({ currentView, navigate }: Props) {
 const isActive = (id: string) => {
 if (id === "home" && currentView === "home") return true;
 if (id === "mybus" && (currentView === "mybus" || currentView === "buspass")) return true;
 if (id === "report" && (currentView === "report" || currentView === "issue-form")) return true;
 if (id === "requests" && (currentView === "requests" || currentView === "request-detail")) return true;
 if (id === "profile" && currentView === "profile") return true;
 return false;
 };

 return (
 <nav className="ms-bottom-nav">
 {navItems.map((item) => (
 <button
 key={item.id}
 className={`ms-nav-item ${isActive(item.id) ? "ms-nav-active" : ""}`}
 onClick={() => navigate(item.id)}
 >
 <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
 <path d={item.icon} />
 </svg>
 <span className="ms-nav-label">{item.label}</span>
 </button>
 ))}
 </nav>
 );
}
","import React, { useState, useEffect, useCallback } from "react";
import "./styles.css";
import HomeScreen from "./components/HomeScreen";
import ReportIssueScreen from "./components/ReportIssueScreen";
import IssueFormScreen from "./components/IssueFormScreen";
import MyBusScreen from "./components/MyBusScreen";
import BusPassScreen from "./components/BusPassScreen";
import MyRequestsScreen from "./components/MyRequestsScreen";
import RequestDetailScreen from "./components/RequestDetailScreen";
import LostFoundScreen from "./components/LostFoundScreen";
import EmergencyScreen from "./components/EmergencyScreen";
import ProfileScreen from "./components/ProfileScreen";
import BottomNav from "./components/BottomNav";

interface ViewState {
 view: string;
 type: string | null;
 id: string | null;
}

function getViewFromUrl(): ViewState {
 const params = new URLSearchParams(window.location.search);
 return {
 view: params.get("view") || "home",
 type: params.get("type") || null,
 id: params.get("id") || null,
 };
}

export default function App() {
 const [currentView, setCurrentView] = useState<ViewState>(getViewFromUrl);

 useEffect(() => {
 const onPopState = () => setCurrentView(getViewFromUrl());
 window.addEventListener("popstate", onPopState);
 return () => window.removeEventListener("popstate", onPopState);
 }, []);

 const navigate = useCallback(
 (viewName: string, extras?: { type?: string; id?: string }) => {
 const params = new URLSearchParams({ view: viewName });
 if (extras?.type) params.set("type", extras.type);
 if (extras?.id) params.set("id", extras.id);
 const path = `${window.location.pathname}?${params}`;
 window.history.pushState({}, "", path);
 setCurrentView({
 view: viewName,
 type: extras?.type || null,
 id: extras?.id || null,
 });
 },
 []
 );

 const { view, type, id } = currentView;

 const renderScreen = () => {
 switch (view) {
 case "home":
 return <HomeScreen navigate={navigate} />;
 case "report":
 return <ReportIssueScreen navigate={navigate} />;
 case "issue-form":
 return <IssueFormScreen navigate={navigate} issueType={type} />;
 case "mybus":
 return <MyBusScreen navigate={navigate} />;
 case "buspass":
 return <BusPassScreen navigate={navigate} />;
 case "requests":
 return <MyRequestsScreen navigate={navigate} />;
 case "request-detail":
 return <RequestDetailScreen navigate={navigate} requestId={id} />;
 case "lostfound":
 return <LostFoundScreen navigate={navigate} />;
 case "emergency":
 return <EmergencyScreen navigate={navigate} />;
 case "profile":
 return <ProfileScreen navigate={navigate} />;
 default:
 return <HomeScreen navigate={navigate} />;
 }
 };

 return (
 <div className="ms-app">
 <div className="ms-content">{renderScreen()}</div>
 <BottomNav currentView={view} navigate={navigate} />
 </div>
 );
}
